// ==========================================================
// MARKET DATA CLEANING + TONNAGE ENRICHMENT
//
// n8n Code Node — JavaScript, "Run Once for All Items" mode
//
// PART 1 — CLASSIFY & CLEAN raw items from four possible source
// shapes (HarvestIQ, OlaNorth, FoodPrices, PriceNija) into one
// consistent record shape.
//
// PART 2 — TONNAGE ENRICHMENT: adds price_per_5_tonnes to every
// record, resolving kg-per-unit via a priority chain (see the
// block above Part 2 for the full explanation), and NEVER
// inventing a weight it can't otherwise justify.
// ==========================================================

function normalizeRegion(r) {
  if (!r) return null;
  const key = String(r).toLowerCase().replace(/[\s-]+/g, '');
  const map = {
    northwest: 'North-West',
    southwest: 'South-West',
    southeast: 'South-East',
    northcentral: 'North-Central',
    southsouth: 'South-South',
    northeast: 'North-East',
  };
  return map[key] || r;
}

function inferRegion(market, state) {
  const m = (market || '').toLowerCase();
  const s = (state || '').toLowerCase();
  const pairs = [
    [['kano', 'kaduna', 'katsina', 'jigawa', 'zamfara', 'sokoto', 'kebbi'], 'North-West'],
    [['lagos', 'ibadan', 'oyo', 'osun', 'ondo', 'ekiti', 'ogun'], 'South-West'],
    [['onitsha', 'enugu', 'anambra', 'imo', 'abia', 'ebonyi'], 'South-East'],
    [['abuja', 'minna', 'makurdi', 'fct', 'niger', 'benue', 'kogi', 'kwara', 'plateau', 'nasarawa'], 'North-Central'],
    [['river', 'delta', 'akwa', 'cross river', 'bayelsa', 'edo'], 'South-South'],
    [['borno', 'yobe', 'adamawa', 'bauchi', 'gombe', 'taraba'], 'North-East'],
  ];
  for (const [keywords, region] of pairs) {
    if (keywords.some((k) => m.includes(k) || s.includes(k))) return region;
  }
  return null;
}

function extractState(market) {
  if (!market) return null;
  const match = market.match(/\((.+?)\)/);
  if (match) {
    const stateMap = { Benue: 'Benue', Lagos: 'Lagos', Oyo: 'Oyo', Niger: 'Niger' };
    return stateMap[match[1]] || match[1];
  }
  return null;
}

function trendFromChange(val) {
  const n = Number(val);
  if (val === undefined || val === null || Number.isNaN(n)) return null;
  if (n > 0) return 'up';
  if (n < 0) return 'down';
  return 'stable';
}

// ==========================================================
// ROBUST NAME/OBJECT EXTRACTION
//
// Some PriceNija-shaped records have shown up with `commodity`
// and `market` as raw JSON-STRINGS (e.g. '{"name":"Maize (White)"}')
// instead of live nested objects — likely from a raw record that
// bypassed proper cleaning somewhere upstream (e.g. an export step
// that serializes objects to text). This makes extraction resilient
// to all three shapes it might arrive in:
//   - a live object          { name: "Maize (White)", state: "Kano", ... }
//   - a JSON-string of that   '{"name":"Maize (White)", "state":"Kano", ...}'
//   - a plain string          "Maize (White)"
// ==========================================================

function tryParseJsonObject(str) {
  if (typeof str !== 'string') return null;
  const trimmed = str.trim();
  if (!trimmed.startsWith('{')) return null;
  try {
    const parsed = JSON.parse(trimmed);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch (e) {
    return null;
  }
}

// Resolves a commodity/market field to its underlying object form
// (with .name, .state, .region, .lat, .lng etc.) whether it arrived
// as a live object or a JSON-stringified one. Returns null if it's
// just a plain string (no extra fields to recover).
function asObject(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  return tryParseJsonObject(value);
}

// Resolves just the display name, whichever shape the field arrived in.
function asName(value) {
  const obj = asObject(value);
  if (obj) return obj.name;
  return typeof value === 'string' ? value : value;
}

// ==========================================================
// PART 2 HELPERS — TONNAGE CONVERSION
//
// Attaches a reliable price_per_5_tonnes to every record, resolving
// kg-per-unit via this priority chain (each used only if the one
// above isn't available):
//
//   1. PROVIDED     — the record's own kgPerUnit field.
//   2. UNIT STRING  — the unit literally states its weight,
//                     e.g. "50kg Bag" -> 50, "10kg" -> 10.
//   3. CROSS-ROW    — another row of the SAME commodity + unit
//                     elsewhere in this batch already has a known
//                     weight (from #1 or #2). Matching uses a
//                     normalized "base commodity" name
//                     (parenthetical qualifiers + plurals
//                     stripped), so "Maize (White)" can borrow the
//                     weight already known for "Maize".
//   4. PRICE-RATIO  — for the SAME commodity, uses rows with a
//                     known weight (steps 1-3) at the SAME market
//                     (preferred) or elsewhere to compute an
//                     average price-per-kg, then divides this
//                     row's price by that rate to back out an
//                     IMPLIED weight. This is an ESTIMATE, not a
//                     verified fact — retail units often carry a
//                     per-kg markup vs bulk units, so this can run
//                     light on small retail sizes. Always tagged
//                     kg_per_unit_source: "price_ratio_estimate".
//   5. UNRESOLVED   — no reliable path found. price_per_5_tonnes stays
//                     null and tonnage_convertible: false — no
//                     invented numbers presented as fact.
//
// Volume units (Liter, 750ml, 1.5L) are never converted to weight —
// that needs a density figure we don't have.
// ==========================================================

function safeFloat(value) {
  if (value === null || value === undefined) return null;
  const text = String(value).replace(/,/g, '').replace(/₦/g, '').trim();
  if (text === '') return null;
  const num = Number(text);
  return Number.isNaN(num) ? null : num;
}

// Lot size the price-per-tonne column is expressed against. Set to
// 5 tonnes to match the assumed truck capacity used for logistics
// cost-per-tonne elsewhere in this pipeline, so a market's
// price_per_5_tonnes lines up directly with one full truckload's
// logistics cost. Change this single constant to re-basis everything
// (e.g. 1000 for a plain per-tonne figure, 30000 for a 30-tonne
// articulated truck).
const TONNE_LOT_SIZE_KG = 5000;

function clean(value) {
  return value === null || value === undefined ? '' : String(value).trim();
}

function parseKgFromUnitString(unitStr) {
  const u = clean(unitStr).toLowerCase();
  if (u === 'kg') return 1;
  const match = u.match(/(\d+(\.\d+)?)\s*kg/);
  if (!match) return null;
  const kg = parseFloat(match[1]);
  return kg > 0 ? kg : null;
}

function normalizeCommodityBase(name) {
  const s = clean(name)
    .replace(/\([^)]*\)/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
  return s.replace(/s$/, '');
}

function normalizeUnit(unit) {
  return clean(unit).toLowerCase();
}

function averagePricePerKg(anchors) {
  if (!anchors || anchors.length === 0) return null;
  const rates = anchors.map((a) => a.price / a.kg).filter((r) => Number.isFinite(r) && r > 0);
  if (rates.length === 0) return null;
  return rates.reduce((sum, r) => sum + r, 0) / rates.length;
}

// Runs the full tonnage resolution chain over an array of cleaned
// record objects (mutates and returns them enriched).
function enrichWithTonnage(records) {
  // Pass 1 — PROVIDED or UNIT STRING only.
  for (const row of records) {
    const explicit = safeFloat(row.kgPerUnit);
    if (explicit !== null && explicit > 0) {
      row._kg = explicit;
      row._kgSource = 'provided';
      continue;
    }
    const parsed = parseKgFromUnitString(row.unit);
    if (parsed !== null) {
      row._kg = parsed;
      row._kgSource = 'parsed_from_unit_string';
      continue;
    }
    row._kg = null;
    row._kgSource = null;
  }

  // Pass 2 — build lookup/anchor tables from what Pass 1 found.
  const knownWeightByCommodityUnit = new Map();
  const anchorsByCommodityMarket = new Map();
  const anchorsByCommodityOnly = new Map();

  for (const row of records) {
    if (row._kg === null) continue;

    const base = normalizeCommodityBase(row.commodity);
    const unit = normalizeUnit(row.unit);
    const market = clean(row.market).toLowerCase();
    const price = safeFloat(row.price);

    const cuKey = `${base}|||${unit}`;
    if (!knownWeightByCommodityUnit.has(cuKey)) {
      knownWeightByCommodityUnit.set(cuKey, row._kg);
    }

    if (price !== null) {
      const cmKey = `${base}|||${market}`;
      if (!anchorsByCommodityMarket.has(cmKey)) anchorsByCommodityMarket.set(cmKey, []);
      anchorsByCommodityMarket.get(cmKey).push({ kg: row._kg, price });

      if (!anchorsByCommodityOnly.has(base)) anchorsByCommodityOnly.set(base, []);
      anchorsByCommodityOnly.get(base).push({ kg: row._kg, price });
    }
  }

  // Pass 3 — CROSS-ROW, then PRICE-RATIO, in that order.
  const volumeUnits = ['liter', '750ml', '1.5l'];

  for (const row of records) {
    if (row._kg !== null) continue;

    const base = normalizeCommodityBase(row.commodity);
    const unit = normalizeUnit(row.unit);
    const market = clean(row.market).toLowerCase();
    const price = safeFloat(row.price);

    if (volumeUnits.includes(unit)) {
      row._kg = null;
      row._kgSource = 'unresolved_volume_unit';
      continue;
    }

    const cuKey = `${base}|||${unit}`;
    if (knownWeightByCommodityUnit.has(cuKey)) {
      row._kg = knownWeightByCommodityUnit.get(cuKey);
      row._kgSource = 'cross_row_known_unit_weight';
      continue;
    }

    if (price === null) {
      row._kg = null;
      row._kgSource = 'unresolved';
      continue;
    }

    const cmKey = `${base}|||${market}`;
    let rate = averagePricePerKg(anchorsByCommodityMarket.get(cmKey));
    let anchorScope = 'same_market';

    if (rate === null) {
      rate = averagePricePerKg(anchorsByCommodityOnly.get(base));
      anchorScope = 'cross_market';
    }

    if (rate !== null) {
      row._kg = Math.round((price / rate) * 1000) / 1000;
      row._kgSource = 'price_ratio_estimate';
      row._anchorScope = anchorScope;
      continue;
    }

    row._kg = null;
    row._kgSource = 'unresolved';
  }

  // Pass 4 — attach final tonnage fields.
  for (const row of records) {
    const price = safeFloat(row.price);
    const kg = row._kg;

    row.kg_per_unit_resolved = kg;
    row.kg_per_unit_source = row._kgSource;
    if (row._anchorScope) row.price_ratio_anchor_scope = row._anchorScope;

    if (kg !== null && kg > 0 && price !== null) {
      row.price_per_5_tonnes = Math.round((price / kg) * TONNE_LOT_SIZE_KG * 100) / 100;
      row.tonnage_convertible = true;
    } else {
      row.price_per_5_tonnes = null;
      row.tonnage_convertible = false;
    }

    delete row._kg;
    delete row._kgSource;
    delete row._anchorScope;
  }

  return records;
}

// ==========================================================
// PART 1 — CLASSIFY & CLEAN
// ==========================================================

const cleaned = [];
const unrecognized = [];

for (const item of $input.all()) {
  const j = item.json;
  if (!j || typeof j !== 'object') {
    unrecognized.push(j);
    continue;
  }

  // --- HarvestIQ: { success, count, prices: [...], fetchedAt } ---
  if (Array.isArray(j.prices)) {
    j.prices.forEach((p) => {
      const entry = {
        source: 'HarvestIQ',
        commodity: p.crop,
        market: p.market,
        price: p.pricePerUnit,
        unit: p.unit,
        kgPerUnit: p.kgPerUnit,
        priceType: 'wholesale',
        currency: 'NGN',
        updatedAt: p.updatedAt,
      };
      const state = extractState(p.market);
      if (state) entry.state = state;
      const region = normalizeRegion(inferRegion(p.market, state));
      if (region) entry.region = region;
      if (p.trend) entry.trend = p.trend;
      if (p.signal) entry.signal = p.signal;
      cleaned.push(entry);
    });
    continue;
  }

  // --- Ola of North: { data: { pageData, record: [...] }, message, succeeded, ... } ---
  if (j.data && Array.isArray(j.data.record)) {
    j.data.record.forEach((p) => {
      const entry = {
        source: 'OlaNorth',
        commodity: p.name,
        price: p.currentPrice,
        unit: p.unit,
        priceType: 'market',
        currency: 'NGN',
        updatedAt: p.lastUpdated || new Date().toISOString(),
      };
      const region = normalizeRegion(p.topRegion);
      if (region) entry.region = region;
      if (p.category) entry.category = p.category;
      const trend = trendFromChange(p.pricePercentageChange);
      if (trend) entry.trend = trend;
      if (typeof p.pricePercentageChange === 'number') entry.priceChangePercent = p.pricePercentageChange;
      cleaned.push(entry);
    });
    continue;
  }

  // --- FoodPrices.ng: { data: [...], stats, pagination, scope, filters } ---
  if (Array.isArray(j.data)) {
    j.data.forEach((p) => {
      const entry = {
        source: 'FoodPrices',
        commodity: p.brand_name || p.name || p.product,
        market: p.market,
        price: p.price !== undefined ? p.price : p.current_price,
        unit: p.quantity || p.unit,
        priceType: 'retail',
        currency: 'NGN',
        updatedAt: p.last_updated || new Date().toISOString(),
      };
      if (p.state) entry.state = p.state;
      const region = normalizeRegion(p.region) || normalizeRegion(inferRegion(p.market, p.state));
      if (region) entry.region = region;
      const trend = trendFromChange(p.change_percent);
      if (trend) entry.trend = trend;
      if (typeof p.change_percent === 'number') entry.priceChangePercent = p.change_percent;
      if (p.url) entry.url = p.url;
      cleaned.push(entry);
    });
    continue;
  }

  // --- PriceNija: each n8n item IS a single flattened record (not wrapped in an array) ---
  // commodity/market use asName()/asObject() so this is resilient even if
  // either field arrives as a JSON-string instead of a live nested object
  // (a shape that has shown up in practice and would otherwise silently
  // produce blank commodity/market/state/region fields).
  if (j.commodity_id !== undefined || j.market_id !== undefined || (j.commodity && j.market)) {
    const p = j;
    const commodityObj = asObject(p.commodity);
    const marketObj = asObject(p.market);

    const entry = {
      source: 'PriceNija',
      commodity: asName(p.commodity),
      market: asName(p.market),
      price: p.price,
      unit: 'bag',
      priceType: p.price_type || 'wholesale',
      currency: 'NGN',
      updatedAt: p.updated_at || p.created_at || new Date().toISOString(),
    };
    const marketState = marketObj?.state;
    if (marketState) entry.state = marketState;
    const region = normalizeRegion(marketObj?.region);
    if (region) entry.region = region;
    if (marketObj?.lat) entry.lat = marketObj.lat;
    if (marketObj?.lng) entry.lng = marketObj.lng;
    if (p.date) entry.date = p.date;
    const commodityCategory = commodityObj?.category;
    if (commodityCategory) entry.category = commodityCategory;
    cleaned.push(entry);
    continue;
  }

  // --- Anything that doesn't match a known shape: keep it visible instead of silently dropping it ---
  unrecognized.push(j);
}

// ==========================================================
// PART 2 — TONNAGE ENRICHMENT (runs across the whole cleaned
// batch at once, since cross-row lookup and price-ratio
// estimation both need to see every record, not just one at a
// time)
// ==========================================================

enrichWithTonnage(cleaned);

const output = cleaned.map((entry) => ({ json: entry }));

if (unrecognized.length) {
  output.push({
    json: {
      source: 'Unrecognized',
      count: unrecognized.length,
      note: 'Items that did not match any known source shape - inspect and extend the classifier above.',
      samples: unrecognized.slice(0, 3),
    },
  });
}

output.sort((a, b) =>
  (a.json.source || '').localeCompare(b.json.source || '') ||
  (a.json.commodity || '').localeCompare(b.json.commodity || '')
);

return output;

// ==========================================================
// DYNAMIC AGRONOMIC SUPPLY CHAIN & MARKET ARBITRAGE ROUTER
// ARBITRAGE CALCULATION — market data + logistics/route data
//
// n8n Code Node — JavaScript, "Run Once for All Items" mode
//
// This version reads a SINGLE merged input stream (Input 0),
// e.g. the output of an upstream Merge node that has already
// combined your market-price rows and your logistics/route
// rows into one array. It auto-sorts each row into either the
// market pile or the route pile by inspecting its fields, so
// you don't need a second Code-node input branch wired up.
//
// MARKET ROW shape, e.g.:
//   {
//     "source": "FoodPrices",
//     "commodity": "Beans (Drum)",
//     "market": "Agbalata Market",
//     "price": 1000,
//     "unit": "1 Derica",
//     "priceType": "retail",
//     "currency": "NGN",
//     "updatedAt": "2026-07-17T01:00:00+01:00",
//     "state": "Lagos",
//     "region": "South-West",
//     ... (optional: trend, priceChangePercent, category, signal, kgPerUnit, date)
//   }
//
// ROUTE ROW shape, e.g. (column names are matched case-
// insensitively, with a couple of common aliases):
//   {
//     "Origin": "Ajah Market",
//     "Destination": "Lekki-Jakande Market",
//     "Est Dist (km)": 8,
//     "Transit Hours": 0.1,
//     "Fuel (L)": 2.9,
//     "Fuel Cost": 4698,
//     "Truck Cost": 256400,
//     "Levy": 75000,
//     "Logistics Cost": 336098
//   }
//
// A row is treated as a ROUTE row if it has origin+destination
// fields, and as a MARKET row if it has commodity+market fields.
// Anything matching neither is skipped.
// ==========================================================

// ==========================================================
// LOAD + SPLIT INPUT
// ==========================================================

const allItems = $input.all();

if (!allItems || allItems.length === 0) {
  throw new Error("No data received.");
}

// Case-insensitive field getter: checks each candidate key against
// every key actually present on the row, ignoring case/whitespace.
function getField(row, candidates) {
  const rowKeys = Object.keys(row);
  for (const candidate of candidates) {
    const normalizedCandidate = candidate.toLowerCase().replace(/[\s_]/g, "");
    for (const key of rowKeys) {
      const normalizedKey = key.toLowerCase().replace(/[\s_]/g, "");
      if (normalizedKey === normalizedCandidate) {
        return row[key];
      }
    }
  }
  return undefined;
}

const marketItems = [];
const routeItems = [];

for (const item of allItems) {
  const row = item.json || item;

  const isRouteRow =
    getField(row, ["Origin", "from"]) !== undefined &&
    getField(row, ["Destination", "to"]) !== undefined;

  const isMarketRow =
    getField(row, ["commodity"]) !== undefined && getField(row, ["market"]) !== undefined;

  if (isRouteRow) {
    routeItems.push(row);
  } else if (isMarketRow) {
    marketItems.push(row);
  }
  // rows matching neither shape are silently skipped
}

if (marketItems.length === 0) {
  throw new Error("No market data rows found in the input (no rows with commodity + market fields).");
}

// ==========================================================
// HELPERS
// ==========================================================

function safeFloat(value) {
  if (value === null || value === undefined) return null;
  try {
    const text = String(value).replace(/,/g, "").replace(/₦/g, "").trim();
    if (text === "") return null;
    const num = Number(text);
    return Number.isNaN(num) ? null : num;
  } catch (e) {
    return null;
  }
}

function clean(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function confidence(count) {
  if (count >= 4) return "Very High";
  if (count === 3) return "High";
  if (count === 2) return "Medium";
  return "Low";
}

function latestTimestamp(values) {
  const timestamps = values.filter((v) => v);
  if (timestamps.length === 0) return null;
  return timestamps.reduce((a, b) => (a > b ? a : b));
}

function mean(values) {
  return values.reduce((a, b) => a + b, 0) / values.length;
}

function round2(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

// Yield all 2-item combinations of an array (mirrors Python's itertools.combinations)
function* combinations2(arr) {
  for (let i = 0; i < arr.length; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      yield [arr[i], arr[j]];
    }
  }
}

// ==========================================================
// LOGISTICS LOOKUP
//
// Built from the route rows split out above. Real-world market
// names are rarely spelled identically across two data sources
// ("Mile 12 Market" vs "Mile 12" vs "Lagos (Mile 12)"), so this
// does two passes when looking up a cost:
//   1. EXACT match on the raw market name.
//   2. NORMALIZED match: strip the word "Market", lowercase,
//      collapse whitespace, and also try whatever's inside
//      parentheses as an alternate name (e.g. "Lagos (Mile 12)"
//      also registers as just "mile 12").
// If neither matches, logistics_cost falls back to 0, same as
// before — this just meaningfully shrinks how often that happens.
// ==========================================================

// Produces every normalized name variant for a market string.
function nameVariants(rawName) {
  const variants = new Set();
  const s = clean(rawName);
  if (!s) return variants;

  const stripMarketWord = (str) =>
    str.replace(/\bmarket\b/gi, "").replace(/\s+/g, " ").trim().toLowerCase();

  // Full name, with/without the word "Market"
  variants.add(s.toLowerCase());
  variants.add(stripMarketWord(s));

  // If there's a parenthetical, e.g. "Lagos (Mile 12)", register
  // both the inner content and the outer name (parens stripped)
  const parenMatch = s.match(/\(([^)]+)\)/);
  if (parenMatch) {
    variants.add(stripMarketWord(parenMatch[1]));
    const outer = s.replace(/\([^)]*\)/, "").replace(/\s+/g, " ").trim();
    if (outer) variants.add(stripMarketWord(outer));
  }

  variants.delete("");
  return variants;
}

const routeLookupExact = new Map();
const routeLookupFuzzy = new Map();

for (const row of routeItems) {
  const originRaw = clean(getField(row, ["Origin", "from"]));
  const destinationRaw = clean(getField(row, ["Destination", "to"]));
  const cost = safeFloat(
    getField(row, [
      "Total Logistics Cost",
      "Logistics Cost",
      "logistics_cost",
      "total_logistics_cost",
      "cost",
      "total_cost",
    ])
  );

  if (!originRaw || !destinationRaw || cost === null) continue;

  routeLookupExact.set(`${originRaw}|||${destinationRaw}`, cost);

  const originVariants = nameVariants(originRaw);
  const destinationVariants = nameVariants(destinationRaw);
  for (const ov of originVariants) {
    for (const dv of destinationVariants) {
      // Don't overwrite an existing fuzzy entry — first match wins,
      // avoiding ambiguous overwrites if two different routes
      // happen to normalize to the same pair.
      const fuzzyKey = `${ov}|||${dv}`;
      if (!routeLookupFuzzy.has(fuzzyKey)) {
        routeLookupFuzzy.set(fuzzyKey, cost);
      }
    }
  }
}

// Looks up logistics cost for a buy/sell market pair. Returns
// { cost, matchType } where matchType is "exact", "fuzzy", or "none".
function lookupLogisticsCost(buyMarket, sellMarket) {
  const exactKey = `${clean(buyMarket)}|||${clean(sellMarket)}`;
  if (routeLookupExact.has(exactKey)) {
    return { cost: routeLookupExact.get(exactKey), matchType: "exact" };
  }

  const buyVariants = nameVariants(buyMarket);
  const sellVariants = nameVariants(sellMarket);
  for (const bv of buyVariants) {
    for (const sv of sellVariants) {
      const fuzzyKey = `${bv}|||${sv}`;
      if (routeLookupFuzzy.has(fuzzyKey)) {
        return { cost: routeLookupFuzzy.get(fuzzyKey), matchType: "fuzzy" };
      }
    }
  }

  return { cost: 0, matchType: "none" };
}

console.log(
  "Route Rows Parsed:",
  routeLookupExact.size,
  "of",
  routeItems.length,
  "route rows found"
);

// ==========================================================
// STEP 1 — BUILD MARKET CONSENSUS
//
// The same commodity+market+unit can appear multiple times
