//     ... (optional: trend, priceChangePercent, category, signal, kgPerUnit, date)
//   }
//
// ROUTE ROW shape, e.g. (column names are matched case-
// insensitively, with a couple of common aliases):
//   {
//     "Origin": "Ajah Market",
//     "Destination": "Lekki-Jakande Market",
