function safeFloat(value) {
  if (value === null || value === undefined) return null;
  try {
    const text = String(value).replace(/,/g, "").replace(/₦/g, "").trim();
    if (text === "") return null;
    const num = Number(text);
    return Number.isNaN(num) ? null : num;
  } catch (e) {
