//   2. NORMALIZED match: strip the word "Market", lowercase,
//      collapse whitespace, and also try whatever's inside
//      parentheses as an alternate name (e.g. "Lagos (Mile 12)"
//      also registers as just "mile 12").
// If neither matches, logistics_cost falls back to 0, same as
// before — this just meaningfully shrinks how often that happens.
// ==========================================================

// Produces every normalized name variant for a market string.
function nameVariants(rawName) {
  const variants = new Set();
  const s = clean(rawName);
  if (!s) return variants;

  const stripMarketWord = (str) =>
    str.replace(/\bmarket\b/gi, "").replace(/\s+/g, " ").trim().toLowerCase();

  // Full name, with/without the word "Market"
  variants.add(s.toLowerCase());
  variants.add(stripMarketWord(s));

  // If there's a parenthetical, e.g. "Lagos (Mile 12)", register
  // both the inner content and the outer name (parens stripped)
  const parenMatch = s.match(/\(([^)]+)\)/);
  if (parenMatch) {
    variants.add(stripMarketWord(parenMatch[1]));
    const outer = s.replace(/\([^)]*\)/, "").replace(/\s+/g, " ").trim();
    if (outer) variants.add(stripMarketWord(outer));
  }

  variants.delete("");
  return variants;
}

